"""Freeze original-float population inventory for physical assembly, without area claims."""
from pathlib import Path
import hashlib,json,math
import numpy as np
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 paths=[Path(__file__),BASE/'model_reference/eventspikeseg140k_float_reference.json',BASE/'model_reference/eventspikeseg140k_float_parameters.npz',BASE/'results/gf180_executed_float_beta_inventory.json',ROOT/'src/eventspikeseg/model.py',ROOT/'src/eventspikeseg/model_components.py',BASE/'assembly/article_module_catalog_v51.json']
 ref=json.loads(paths[1].read_text());inv=json.loads(paths[3].read_text());assert ref['checkpoint_sha256']==inv['checkpoint_sha256'];data=np.load(paths[2]);meta={a['name']:a for a in ref['effective_folded_weight_and_neuron_parameters']};rows=[]
 for a in inv['actors']:
  name=a['actor'];m=meta[name];key=name.replace('.','__');weight=data['weight__'+key];assert list(weight.shape)==m['weight_shape_oihw'];n=len(a['beta']);assert weight.shape[0]==n
  pixels=a['states_per_channel'];scale=math.isqrt(440*640//pixels);assert (440//scale)*(640//scale)==pixels
  adapt=bool(m['threshold_adaptation_enabled']);total=n*pixels
  rows.append({'actor':name,'channels':n,'height':440//scale,'width':640//scale,'resident_membranes':total,'adaptation_enabled':adapt,'resident_age_states':total if adapt else 0,'resident_amplitude_states':total if adapt else 0,'peer_inhibition_enabled':bool(m['inhibition_enabled']),'synaptic_weight_count':int(weight.size),'synaptic_weight_shape_oihw':list(weight.shape),'stride':m['conv_stride'],'groups':m['conv_groups'],'dilation':m['conv_dilation'],'float_weight_array':'weight__'+key,'float_beta_array':'beta__'+key,'float_threshold_array':'threshold__'+key,'beta_min':min(a['beta']),'beta_max':max(a['beta']),'dense_physical_instance_map':None,'dense_layout_qualified':False,'characterization_geometry_is_not_dense_area':True})
 mem=sum(a['resident_membranes'] for a in rows);adapt=sum(a['resident_age_states'] for a in rows);weights=sum(a['synaptic_weight_count'] for a in rows);readout=int(data['weight__head_synapse'].size);assert readout==ref['readout_weight']['count'];assert mem==30976000 and adapt==10982400 and weights+readout==143824 and readout==96
 classstates=6*440*640;p=BASE/'assembly/full25actor_original_float_population_manifest_v1.json';assert not p.exists()
 r={'inventory_preparation_completed':True,'checkpoint_sha256':ref['checkpoint_sha256'],'actor_count':len(rows),'actors':rows,'resident_membranes':mem,'resident_adaptation_age_states':adapt,'resident_adaptation_amplitude_states':adapt,'readout':{'class_count':6,'height':440,'width':640,'resident_class_current_states':classstates,'synaptic_weights':readout,'ten_bins_accumulated':10,'is_PLIF':False},'synaptic_weights':weights+readout,'executed_beta_channels':sum(a['channels'] for a in rows),'minimum_logical_analog_state_nodes_excluding_auxiliary_and_parameters':mem+2*adapt+classstates,'assembly_contract':{'all_actor_state_identities_permanent':True,'no_cross_actor_state_aliasing':True,'bin_us':5000,'record_us':50000,'threshold_after_all_signed_contributions':True,'beta_once_per_bin_including_no_event':True,'continuous_trained_adaptation_duration':True,'raw_event_multiplicity_preserved':True,'project2_x1_merge_preserves_multiplicity':True,'categorical_control_bits_allowed':True,'quantized_numerical_state':False},'scope':'Exact original-float layout population inputs, not a completed placement/netlist or measured chip area. Qualified characterization assemblies provide reusable circuit evidence; spacious fixtures must not be replicated as dense area. Dense per-state geometry, all1856 trained beta mappings, parameter/weight programming and hierarchy/interconnect/service remain incomplete. Full native model SPICE is not required or attempted.','full_chip_layout_complete':False,'original_float_accuracy_accepted':False,'full_5ms_population_service_accepted':False,'sha256':{p.relative_to(ROOT).as_posix():sha(p) for p in paths}}
 p.write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:r[k] for k in ['actor_count','resident_membranes','resident_adaptation_age_states','synaptic_weights','minimum_logical_analog_state_nodes_excluding_auxiliary_and_parameters']},indent=2))
if __name__=='__main__':main()
